import{DesignSystemManager as s}from"../../d-d-d/lib/DesignSystemManager.js";import{ShadcnTokens as e,ShadcnFonts as n}from"./ShadcnTokens.js";import{ShadcnDDDMap as t,ShadcnColorNames as a}from"./ShadcnDDDMap.js";import{ShadcnIcons as r}from"./ShadcnIcons.js";export const SHADCN_SYSTEM="shadcn";export function registerShadcnDesignSystem(c=s){return c&&!c.systems.shadcn&&c.addDesignSystem({name:"shadcn",extends:"ddd",styles:[e,t],fonts:n,colorNames:a,icons:r}),c}export function activateShadcnDesignSystem(e=s){return registerShadcnDesignSystem(e),e&&"shadcn"!==e.active&&(e.active="shadcn"),e}